insert into public.translations (locale, key, value) values
  ('pt-BR', 'admin.description', $json$"Ligue ou desligue recursos para todos e monte os planos à venda."$json$::jsonb),
  ('en', 'admin.description', $json$"Turn features on or off for everyone and set up the plans for sale."$json$::jsonb),
  ('es', 'admin.description', $json$"Activa o desactiva funciones para todos y configura los planes a la venta."$json$::jsonb),
  ('zh-CN', 'admin.description', $json$"为所有人开启或关闭功能，并设置在售套餐。"$json$::jsonb),
  ('hi', 'admin.description', $json$"सबके लिए सुविधाएँ चालू या बंद करें और बिक्री के प्लान सेट करें।"$json$::jsonb),
  ('ar', 'admin.description', $json$"فعّل الميزات أو عطّلها للجميع وأعدّ الخطط المعروضة للبيع."$json$::jsonb),
  ('fr', 'admin.description', $json$"Activez ou désactivez des fonctionnalités pour tous et configurez les forfaits en vente."$json$::jsonb),
  ('ru', 'admin.description', $json$"Включайте и выключайте функции для всех и настраивайте тарифы в продаже."$json$::jsonb),
  ('ja', 'admin.description', $json$"全員向けに機能をオン／オフし、販売するプランを設定します。"$json$::jsonb),
  ('de', 'admin.description', $json$"Schalte Funktionen für alle ein oder aus und richte die Pläne zum Verkauf ein."$json$::jsonb),
  ('pt-BR', 'agent.approveMcps.hint.cli', $json$"Entrega a este agente os servidores da aba MCP e deixa ele usar as ferramentas deles sem perguntar. Desligado, ele não recebe nenhum."$json$::jsonb),
  ('en', 'agent.approveMcps.hint.cli', $json$"Gives this agent the servers from the MCP tab and lets it use their tools without asking. When off, it gets none."$json$::jsonb),
  ('es', 'agent.approveMcps.hint.cli', $json$"Entrega a este agente los servidores de la pestaña MCP y le permite usar sus herramientas sin preguntar. Desactivado, no recibe ninguno."$json$::jsonb),
  ('zh-CN', 'agent.approveMcps.hint.cli', $json$"把 MCP 标签页中的服务器提供给此代理，并允许它无需询问即可使用其工具。关闭时不提供任何服务器。"$json$::jsonb),
  ('hi', 'agent.approveMcps.hint.cli', $json$"इस एजेंट को MCP टैब के सर्वर देता है और उनके टूल बिना पूछे इस्तेमाल करने देता है। बंद होने पर उसे कोई नहीं मिलता।"$json$::jsonb),
  ('ar', 'agent.approveMcps.hint.cli', $json$"يعطي هذا الوكيل خوادم تبويب MCP ويتيح له استخدام أدواتها دون سؤال. عند الإيقاف لا يحصل على أي منها."$json$::jsonb),
  ('fr', 'agent.approveMcps.hint.cli', $json$"Donne à cet agent les serveurs de l’onglet MCP et le laisse utiliser leurs outils sans demander. Désactivé, il n’en reçoit aucun."$json$::jsonb),
  ('ru', 'agent.approveMcps.hint.cli', $json$"Передаёт этому агенту серверы со вкладки MCP и разрешает пользоваться их инструментами без вопросов. Если выключено, он не получает ни одного."$json$::jsonb),
  ('ja', 'agent.approveMcps.hint.cli', $json$"MCP タブのサーバーをこのエージェントに渡し、確認なしでツールを使えるようにします。オフのときは何も渡しません。"$json$::jsonb),
  ('de', 'agent.approveMcps.hint.cli', $json$"Gibt diesem Agenten die Server aus dem Tab MCP und lässt ihn ihre Werkzeuge ohne Nachfrage nutzen. Ausgeschaltet bekommt er keine."$json$::jsonb),
  ('pt-BR', 'agent.approveMcps.hint.cursor', $json$"Põe os servidores da aba MCP no arquivo MCP do agente, sem mexer no resto, e deixa o agente usar todos os servidores MCP sem perguntar."$json$::jsonb),
  ('en', 'agent.approveMcps.hint.cursor', $json$"Adds the servers from the MCP tab to the agent's MCP file, keeping the rest of it, and lets the agent use every MCP server without asking."$json$::jsonb),
  ('es', 'agent.approveMcps.hint.cursor', $json$"Añade los servidores de la pestaña MCP al archivo MCP del agente, sin tocar el resto, y le permite usar todos los servidores MCP sin preguntar."$json$::jsonb),
  ('zh-CN', 'agent.approveMcps.hint.cursor', $json$"将 MCP 标签页中的服务器添加到代理的 MCP 文件（其余内容保持不变），并允许代理无需询问即可使用所有 MCP 服务器。"$json$::jsonb),
  ('hi', 'agent.approveMcps.hint.cursor', $json$"MCP टैब के सर्वर एजेंट की MCP फ़ाइल में जोड़ता है, बाकी को वैसा ही रखते हुए, और एजेंट को हर MCP सर्वर बिना पूछे इस्तेमाल करने देता है।"$json$::jsonb),
  ('ar', 'agent.approveMcps.hint.cursor', $json$"يضيف خوادم تبويب MCP إلى ملف MCP الخاص بالوكيل مع إبقاء باقيه كما هو، ويتيح للوكيل استخدام كل خوادم MCP دون سؤال."$json$::jsonb),
  ('fr', 'agent.approveMcps.hint.cursor', $json$"Ajoute les serveurs de l’onglet MCP au fichier MCP de l’agent, sans toucher au reste, et le laisse utiliser tous les serveurs MCP sans demander."$json$::jsonb),
  ('ru', 'agent.approveMcps.hint.cursor', $json$"Добавляет серверы со вкладки MCP в файл MCP агента, не трогая остальное, и разрешает агенту пользоваться всеми серверами MCP без вопросов."$json$::jsonb),
  ('ja', 'agent.approveMcps.hint.cursor', $json$"MCP タブのサーバーをエージェントの MCP ファイルに追加し（他の内容はそのまま）、すべての MCP サーバーを確認なしで使えるようにします。"$json$::jsonb),
  ('de', 'agent.approveMcps.hint.cursor', $json$"Fügt die Server aus dem Tab MCP zur MCP-Datei des Agenten hinzu, ohne den Rest zu ändern, und lässt den Agenten jeden MCP-Server ohne Nachfrage nutzen."$json$::jsonb),
  ('pt-BR', 'agent.approveMcps.hint.gateway', $json$"Inicia os servidores da aba MCP e deixa o modelo usar as ferramentas deles sem perguntar. Desligado, ele responde só com texto."$json$::jsonb),
  ('en', 'agent.approveMcps.hint.gateway', $json$"Starts the servers from the MCP tab and lets the model use their tools without asking. When off, it answers with text only."$json$::jsonb),
  ('es', 'agent.approveMcps.hint.gateway', $json$"Inicia los servidores de la pestaña MCP y permite al modelo usar sus herramientas sin preguntar. Desactivado, solo responde con texto."$json$::jsonb),
  ('zh-CN', 'agent.approveMcps.hint.gateway', $json$"启动 MCP 标签页中的服务器，并允许模型无需询问即可使用其工具。关闭时只返回文本回答。"$json$::jsonb),
  ('hi', 'agent.approveMcps.hint.gateway', $json$"MCP टैब के सर्वर शुरू करता है और मॉडल को उनके टूल बिना पूछे इस्तेमाल करने देता है। बंद होने पर सिर्फ़ टेक्स्ट में जवाब देता है।"$json$::jsonb),
  ('ar', 'agent.approveMcps.hint.gateway', $json$"يشغّل خوادم تبويب MCP ويتيح للنموذج استخدام أدواتها دون سؤال. عند الإيقاف يجيب بالنص فقط."$json$::jsonb),
  ('fr', 'agent.approveMcps.hint.gateway', $json$"Démarre les serveurs de l’onglet MCP et laisse le modèle utiliser leurs outils sans demander. Désactivé, il répond en texte uniquement."$json$::jsonb),
  ('ru', 'agent.approveMcps.hint.gateway', $json$"Запускает серверы со вкладки MCP и разрешает модели пользоваться их инструментами без вопросов. Если выключено, отвечает только текстом."$json$::jsonb),
  ('ja', 'agent.approveMcps.hint.gateway', $json$"MCP タブのサーバーを起動し、モデルが確認なしでツールを使えるようにします。オフのときはテキストだけで回答します。"$json$::jsonb),
  ('de', 'agent.approveMcps.hint.gateway', $json$"Startet die Server aus dem Tab MCP und lässt das Modell ihre Werkzeuge ohne Nachfrage nutzen. Ausgeschaltet antwortet es nur mit Text."$json$::jsonb),
  ('pt-BR', 'agent.claude.tagline', $json$"Agente de código com permissões, esforço de raciocínio e orçamento por pedido."$json$::jsonb),
  ('en', 'agent.claude.tagline', $json$"Coding agent with permissions, reasoning effort and a budget per request."$json$::jsonb),
  ('es', 'agent.claude.tagline', $json$"Agente de código con permisos, esfuerzo de razonamiento y presupuesto por solicitud."$json$::jsonb),
  ('zh-CN', 'agent.claude.tagline', $json$"编程代理，支持权限、推理强度和单次请求预算。"$json$::jsonb),
  ('hi', 'agent.claude.tagline', $json$"कोडिंग एजेंट, अनुमतियों, तर्क-प्रयास और हर अनुरोध के बजट के साथ।"$json$::jsonb),
  ('ar', 'agent.claude.tagline', $json$"وكيل برمجة مع أذونات وجهد استدلال وميزانية لكل طلب."$json$::jsonb),
  ('fr', 'agent.claude.tagline', $json$"Agent de code avec autorisations, effort de raisonnement et budget par demande."$json$::jsonb),
  ('ru', 'agent.claude.tagline', $json$"Агент для кода с разрешениями, уровнем рассуждения и бюджетом на запрос."$json$::jsonb),
  ('ja', 'agent.claude.tagline', $json$"権限、推論の強さ、リクエストごとの予算を設定できるコーディングエージェント。"$json$::jsonb),
  ('de', 'agent.claude.tagline', $json$"Coding-Agent mit Berechtigungen, Denkaufwand und Budget pro Anfrage."$json$::jsonb),
  ('pt-BR', 'agent.codex.tagline', $json$"Agente de código que trabalha dentro de uma sandbox."$json$::jsonb),
  ('en', 'agent.codex.tagline', $json$"Coding agent that works inside a sandbox."$json$::jsonb),
  ('es', 'agent.codex.tagline', $json$"Agente de código que trabaja dentro de un sandbox."$json$::jsonb),
  ('zh-CN', 'agent.codex.tagline', $json$"在沙盒中工作的编程代理。"$json$::jsonb),
  ('hi', 'agent.codex.tagline', $json$"सैंडबॉक्स के अंदर काम करने वाला कोडिंग एजेंट।"$json$::jsonb),
  ('ar', 'agent.codex.tagline', $json$"وكيل برمجة يعمل داخل بيئة معزولة."$json$::jsonb),
  ('fr', 'agent.codex.tagline', $json$"Agent de code qui travaille dans un bac à sable."$json$::jsonb),
  ('ru', 'agent.codex.tagline', $json$"Агент для кода, работающий в песочнице."$json$::jsonb),
  ('ja', 'agent.codex.tagline', $json$"サンドボックス内で動くコーディングエージェント。"$json$::jsonb),
  ('de', 'agent.codex.tagline', $json$"Coding-Agent, der in einer Sandbox arbeitet."$json$::jsonb),
  ('pt-BR', 'agent.command.locked', $json$"Fixo para este agente."$json$::jsonb),
  ('en', 'agent.command.locked', $json$"Fixed for this agent."$json$::jsonb),
  ('es', 'agent.command.locked', $json$"Fijo para este agente."$json$::jsonb),
  ('zh-CN', 'agent.command.locked', $json$"此代理的固定值。"$json$::jsonb),
  ('hi', 'agent.command.locked', $json$"इस एजेंट के लिए तय है।"$json$::jsonb),
  ('ar', 'agent.command.locked', $json$"ثابت لهذا الوكيل."$json$::jsonb),
  ('fr', 'agent.command.locked', $json$"Fixé pour cet agent."$json$::jsonb),
  ('ru', 'agent.command.locked', $json$"Фиксировано для этого агента."$json$::jsonb),
  ('ja', 'agent.command.locked', $json$"このエージェントでは固定です。"$json$::jsonb),
  ('de', 'agent.command.locked', $json$"Für diesen Agenten fest vorgegeben."$json$::jsonb),
  ('pt-BR', 'agent.copilot.tagline', $json$"Agente de código com acesso às ferramentas sob o seu controle."$json$::jsonb),
  ('en', 'agent.copilot.tagline', $json$"Coding agent with tool access under your control."$json$::jsonb),
  ('es', 'agent.copilot.tagline', $json$"Agente de código con acceso a herramientas bajo tu control."$json$::jsonb),
  ('zh-CN', 'agent.copilot.tagline', $json$"编程代理，工具访问由你控制。"$json$::jsonb),
  ('hi', 'agent.copilot.tagline', $json$"कोडिंग एजेंट, टूल की पहुँच आपके नियंत्रण में।"$json$::jsonb),
  ('ar', 'agent.copilot.tagline', $json$"وكيل برمجة مع وصول إلى الأدوات تحت سيطرتك."$json$::jsonb),
  ('fr', 'agent.copilot.tagline', $json$"Agent de code avec un accès aux outils que vous contrôlez."$json$::jsonb),
  ('ru', 'agent.copilot.tagline', $json$"Агент для кода с доступом к инструментам под вашим контролем."$json$::jsonb),
  ('ja', 'agent.copilot.tagline', $json$"ツールへのアクセスを自分で管理できるコーディングエージェント。"$json$::jsonb),
  ('de', 'agent.copilot.tagline', $json$"Coding-Agent mit Werkzeugzugriff unter deiner Kontrolle."$json$::jsonb),
  ('pt-BR', 'agent.cursor.tagline', $json$"Agente de código com sandbox e modelos próprios."$json$::jsonb),
  ('en', 'agent.cursor.tagline', $json$"Coding agent with its own sandbox and models."$json$::jsonb),
  ('es', 'agent.cursor.tagline', $json$"Agente de código con su propio sandbox y modelos."$json$::jsonb),
  ('zh-CN', 'agent.cursor.tagline', $json$"拥有自己的沙盒和模型的编程代理。"$json$::jsonb),
  ('hi', 'agent.cursor.tagline', $json$"अपने सैंडबॉक्स और मॉडल वाला कोडिंग एजेंट।"$json$::jsonb),
  ('ar', 'agent.cursor.tagline', $json$"وكيل برمجة ببيئته المعزولة ونماذجه الخاصة."$json$::jsonb),
  ('fr', 'agent.cursor.tagline', $json$"Agent de code avec son propre bac à sable et ses modèles."$json$::jsonb),
  ('ru', 'agent.cursor.tagline', $json$"Агент для кода со своей песочницей и моделями."$json$::jsonb),
  ('ja', 'agent.cursor.tagline', $json$"独自のサンドボックスとモデルを持つコーディングエージェント。"$json$::jsonb),
  ('de', 'agent.cursor.tagline', $json$"Coding-Agent mit eigener Sandbox und eigenen Modellen."$json$::jsonb),
  ('pt-BR', 'agent.effort.hint.auto', $json$"Automático deixa o Jev escolher a cada pedido. Mais esforço dá respostas melhores, mas demora e custa mais."$json$::jsonb),
  ('en', 'agent.effort.hint.auto', $json$"Automatic lets Jev pick for each request. More effort gives better answers but takes longer and costs more."$json$::jsonb),
  ('es', 'agent.effort.hint.auto', $json$"Automático deja que Jev elija en cada solicitud. Más esfuerzo da mejores respuestas, pero tarda más y cuesta más."$json$::jsonb),
  ('zh-CN', 'agent.effort.hint.auto', $json$"“自动”让 Jev 为每个请求选择。强度越高回答越好，但耗时更长、成本更高。"$json$::jsonb),
  ('hi', 'agent.effort.hint.auto', $json$"स्वचालित से Jev हर अनुरोध के लिए चुनता है। ज़्यादा प्रयास से जवाब बेहतर होते हैं, पर समय और खर्च बढ़ता है।"$json$::jsonb),
  ('ar', 'agent.effort.hint.auto', $json$"«تلقائي» يترك Jev يختار لكل طلب. الجهد الأكبر يعطي إجابات أفضل لكنه يستغرق وقتًا أطول ويكلّف أكثر."$json$::jsonb),
  ('fr', 'agent.effort.hint.auto', $json$"Automatique laisse Jev choisir pour chaque demande. Plus d’effort donne de meilleures réponses, mais prend plus de temps et coûte plus."$json$::jsonb),
  ('ru', 'agent.effort.hint.auto', $json$"«Автоматически» — Jev выбирает для каждого запроса. Больше усилий — лучше ответы, но дольше и дороже."$json$::jsonb),
  ('ja', 'agent.effort.hint.auto', $json$"「自動」ではリクエストごとに Jev が選びます。強いほど回答は良くなりますが、時間と費用がかかります。"$json$::jsonb),
  ('de', 'agent.effort.hint.auto', $json$"Automatisch lässt Jev für jede Anfrage wählen. Mehr Aufwand liefert bessere Antworten, dauert aber länger und kostet mehr."$json$::jsonb),
  ('pt-BR', 'agent.kilo.tagline', $json$"Agente de linha de comando com aprovação automática no modo Desenvolvimento."$json$::jsonb),
  ('en', 'agent.kilo.tagline', $json$"Command-line agent with auto-approve in Development mode."$json$::jsonb),
  ('es', 'agent.kilo.tagline', $json$"Agente de línea de comandos con aprobación automática en modo Desarrollo."$json$::jsonb),
  ('zh-CN', 'agent.kilo.tagline', $json$"命令行代理，在开发模式下自动批准。"$json$::jsonb),
  ('hi', 'agent.kilo.tagline', $json$"कमांड-लाइन एजेंट, डेवलपमेंट मोड में अपने-आप मंज़ूरी के साथ।"$json$::jsonb),
  ('ar', 'agent.kilo.tagline', $json$"وكيل سطر أوامر مع موافقة تلقائية في وضع التطوير."$json$::jsonb),
  ('fr', 'agent.kilo.tagline', $json$"Agent en ligne de commande avec approbation automatique en mode Développement."$json$::jsonb),
  ('ru', 'agent.kilo.tagline', $json$"Агент командной строки с автоодобрением в режиме «Разработка»."$json$::jsonb),
  ('ja', 'agent.kilo.tagline', $json$"開発モードで自動承認するコマンドラインエージェント。"$json$::jsonb),
  ('de', 'agent.kilo.tagline', $json$"Kommandozeilen-Agent mit automatischer Freigabe im Modus Entwicklung."$json$::jsonb),
  ('pt-BR', 'agent.litellm.tagline', $json$"O seu próprio proxy, com os modelos que você configurou nele. Responde só com texto."$json$::jsonb),
  ('en', 'agent.litellm.tagline', $json$"Your own proxy, with the models you set up there. Text answers only."$json$::jsonb),
  ('es', 'agent.litellm.tagline', $json$"Tu propio proxy, con los modelos que configuraste en él. Solo responde con texto."$json$::jsonb),
  ('zh-CN', 'agent.litellm.tagline', $json$"你自己的代理服务器，使用你在其中配置的模型。只返回文本回答。"$json$::jsonb),
  ('hi', 'agent.litellm.tagline', $json$"आपका अपना प्रॉक्सी, उसमें सेट किए मॉडल के साथ। सिर्फ़ टेक्स्ट में जवाब।"$json$::jsonb),
  ('ar', 'agent.litellm.tagline', $json$"الوكيل الخاص بك، مع النماذج التي أعددتها فيه. إجابات نصية فقط."$json$::jsonb),
  ('fr', 'agent.litellm.tagline', $json$"Votre propre proxy, avec les modèles que vous y avez configurés. Réponses en texte uniquement."$json$::jsonb),
  ('ru', 'agent.litellm.tagline', $json$"Ваш собственный прокси с настроенными в нём моделями. Отвечает только текстом."$json$::jsonb),
