  ('en', 'agent.loggedOut', $json$"Found at {path}, but not signed in. Sign in from the terminal; until then, requests go to other agents."$json$::jsonb),
  ('es', 'agent.loggedOut', $json$"Encontrado en {path}, pero sin sesión iniciada. Inicia sesión desde la terminal; mientras tanto, las solicitudes van a otros agentes."$json$::jsonb),
