  ('hi', 'feature.mcp.detail', $json$"MCP सर्वर एजेंटों से जोड़ें, आपके अपने और संगठन के।"$json$::jsonb),
  ('ar', 'feature.mcp.detail', $json$"اربط خوادم MCP بالوكلاء، خوادمك وخوادم المؤسسة."$json$::jsonb),
