  ('de', 'feature.mcp.detail', $json$"Verbinde MCP-Server mit den Agenten, deine eigenen und die der Organisation."$json$::jsonb),
  ('pt-BR', 'feature.parallelTasks.detail', $json$"Um pedido grande é dividido entre agentes que trabalham ao mesmo tempo."$json$::jsonb),
