  ('zh-CN', 'mode.build.hint', $json$"代理在允许的权限内修改项目文件"$json$::jsonb),
  ('hi', 'mode.build.hint', $json$"एजेंट दी गई अनुमतियों के भीतर प्रोजेक्ट की फ़ाइलें बदलता है"$json$::jsonb),
  ('ar', 'mode.build.hint', $json$"يغيّر الوكيل ملفات المشروع ضمن الأذونات المسموح بها"$json$::jsonb),
