  ('en', 'model.refresh.running', $json$"Loading models…"$json$::jsonb),
  ('es', 'model.refresh.running', $json$"Cargando modelos…"$json$::jsonb),
  ('zh-CN', 'model.refresh.running', $json$"正在加载模型…"$json$::jsonb),
  ('hi', 'model.refresh.running', $json$"मॉडल लोड हो रहे हैं…"$json$::jsonb),
