  ('en', 'org.gitNamespaceMissing', $json$"First choose which account in the git provider belongs to this organization."$json$::jsonb),
  ('es', 'org.gitNamespaceMissing', $json$"Primero elige qué cuenta del proveedor git pertenece a esta organización."$json$::jsonb),
