  ('ar', 'org.gitNamespaceMissing', $json$"اختر أولًا الحساب في مزوّد git الذي ينتمي إلى هذه المؤسسة."$json$::jsonb),
  ('fr', 'org.gitNamespaceMissing', $json$"Choisissez d’abord quel compte du fournisseur git appartient à cette organisation."$json$::jsonb),
