  ('hi', 'usage.quota.silent', $json$"{agent} ने समय पर अपनी सीमाएँ नहीं बताईं।"$json$::jsonb),
  ('ar', 'usage.quota.silent', $json$"لم يُبلغ {agent} عن حدوده في الوقت المناسب."$json$::jsonb),
  ('fr', 'usage.quota.silent', $json$"{agent} n’a pas indiqué ses limites à temps."$json$::jsonb),
  ('ru', 'usage.quota.silent', $json$"{agent} не сообщил свои лимиты вовремя."$json$::jsonb),
  ('ja', 'usage.quota.silent', $json$"{agent} が時間内に上限を報告しませんでした。"$json$::jsonb),
  ('de', 'usage.quota.silent', $json$"{agent} hat seine Limits nicht rechtzeitig gemeldet."$json$::jsonb),
